<?php
namespace Src\Facturacion\Infrastructure\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Src\OrdenTrabajo\Infrastructure\Models\OrdenTrabajoEloquentModel;
class FacturaOrdenEloquentModel extends Model{use HasUuids;protected $table='facturas_orden';protected $fillable=['numero','orden_id','cliente_tipo_documento','cliente_documento','cliente_nombre','cliente_direccion','cliente_email','vehiculo_placa','subtotal','descuento','motivo_descuento','descuento_autorizado_por','descuento_autorizado_en','base_impuesto','tasa_impuesto','impuesto','total','moneda','estado','emitida_en','vence_en','observaciones','emitida_por','anulada_en','anulada_por','motivo_anulacion'];protected function casts():array{return['subtotal'=>'decimal:2','descuento'=>'decimal:2','base_impuesto'=>'decimal:2','tasa_impuesto'=>'decimal:2','impuesto'=>'decimal:2','total'=>'decimal:2','emitida_en'=>'immutable_datetime','vence_en'=>'immutable_date','descuento_autorizado_en'=>'immutable_datetime','anulada_en'=>'immutable_datetime'];}public function orden():BelongsTo{return$this->belongsTo(OrdenTrabajoEloquentModel::class,'orden_id');}public function lineas():HasMany{return$this->hasMany(FacturaOrdenLineaEloquentModel::class,'factura_id');}public function historial():HasMany{return$this->hasMany(FacturaOrdenHistorialEloquentModel::class,'factura_id');}}
